// Monta o pedido pra OpenAI com os dados do produto que o Meu Custo Total manda
const b = $json.body || {};
const p = b.product || {};
const money = (v) => (v == null ? '' : 'R$ ' + Number(v).toFixed(2).replace('.', ','));

const facts = [
  `Loja: ${b.store || ''}`,
  b.segment ? `Ramo: ${b.segment}` : null,
  `Produto: ${p.name || ''}`,
  p.category ? `Categoria: ${p.category}` : null,
  p.description ? `Descrição: ${String(p.description).slice(0, 1200)}` : null,
  p.original_price ? `Está em promoção (de ${money(p.original_price)} por ${money(p.price)})` : null,
  p.made_to_order ? 'Feito sob encomenda' : null,
].filter(Boolean).join('\n');

const system = [
  'Você escreve textos curtos de oferta para grupos de WhatsApp de pequenas lojas brasileiras.',
  'Regras:',
  '- Português do Brasil, tom animado e próximo, sem exagero.',
  '- No máximo 3 frases curtas (até 350 caracteres no total).',
  '- Pode usar até 2 emojis e *negrito* do WhatsApp em no máximo 2 palavras.',
  '- NÃO escreva preço, valores, links, hashtags, nome da loja nem "clique no link": o sistema já coloca preço e link.',
  '- Use só características que estão na descrição; não invente medidas, materiais nem prazos.',
  '- Responda só com o texto, sem aspas.',
].join('\n');

const user = facts + (b.instructions ? `\n\nPedido do lojista: ${String(b.instructions).slice(0, 300)}` : '');

return [{
  json: {
    body: {
      model: 'gpt-4o-mini',
      temperature: 0.8,
      max_tokens: 220,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
}];
